Execute the supplied Rego v0 admission policy on the supplied input and base data.
Evaluate the query data.k8spspflexvolumes.violation. HOLD means one or more violation objects; ALLOW means zero violation objects.
Return exactly one JSON object with these fields:
- "action": "ALLOW" or "HOLD"
- "violation_count": the exact number of distinct violation objects
- "subject": the reviewed object as {"kind", "namespace", "name"}
- "rule_id": "FLEXVOLUME_DRIVER" for HOLD and "NONE" for ALLOW
- "witnesses": one {"kind", "namespace", "name"} object per violation; use kind FlexVolume, namespace "", and the volume name for FlexVolume witnesses
Use the policy, input, and base data as the complete execution state.

POLICY SOURCE
package k8spspflexvolumes

violation[{"msg": msg, "details": {}}] {
    volume := input_flexvolumes[_]
    not input_flexvolumes_allowed(volume)
    msg := sprintf("FlexVolume %v is not allowed, pod: %v. Allowed drivers: %v", [volume, input.review.object.metadata.name, input.parameters.allowedFlexVolumes])
}

input_flexvolumes_allowed(volume) {
    input.parameters.allowedFlexVolumes[_].driver == volume.flexVolume.driver
}

input_flexvolumes[v] {
    v := input.review.object.spec.volumes[_]
    has_field(v, "flexVolume")
}

# has_field returns whether an object has a field
has_field(object, field) = true {
    object[field]
}

INPUT JSON
